using System;using System.IO;using System.Linq;using System.Reflection;using System.Windows.Forms;using System.Collections.Generic;using System.Drawing;using V15Voice;
public static class CreatorImportUiTests {
 static int count,code;static object F(object f,string n){return f.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(f);}static object C(object f,string n,params object[] a){return f.GetType().GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(f,a);}static void Check(bool b,string n){if(!b)throw new Exception(n);Console.WriteLine("PASS "+n);count++;}
 static void Drop(Control target,string path){var data=new DataObject(DataFormats.FileDrop,new[]{path});typeof(Control).GetMethod("OnDragDrop",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(target,new object[]{new DragEventArgs(data,0,0,0,DragDropEffects.Copy,DragDropEffects.Copy)});Application.DoEvents();}
 [STAThread]public static void Main(){Application.EnableVisualStyles();var f=new MainForm();f.Shown+=(s,e)=>{try{
 var tabs=(TabControl)F(f,"tabs");tabs.SelectedTab=(TabPage)F(f,"creatorPage");var inner=(TabControl)F(f,"creatorTabs");var videos=(DataGridView)F(f,"creatorVideoFiles");var files=(DataGridView)F(f,"creatorFiles");var info=(Label)F(f,"creatorImportInfo");
 string d=Path.Combine(Path.GetTempPath(),"V15 ghép khác tên "+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(d);string v=Path.Combine(d,"DEN CJ -1.mp4"),a=Path.Combine(d,"coca1.srt"),b=Path.Combine(d,"coca2.srt"),v2=Path.Combine(d,"DEN CJ -2.MOV");File.WriteAllText(v,"test fixture");File.WriteAllText(v2,"test fixture");string srt=Scripts.ToSrt(new List<Cue>{new Cue{Id=1,Start=0,End=4,Text="A nice story starts here."}});File.WriteAllText(a,srt);File.WriteAllText(b,srt);
 C(f,"CreatorImportPaths",(object)new[]{v});Check(videos.Rows.Count==1&&files.Rows.Count==0,"Video-first import is visible without any SRT");Check(info.Text.Contains("thêm 1 video"),"Video-first import confirms received count");Check(videos.Rows[0].Cells[1].Value.ToString().Contains("Chưa ghép"),"Unpaired video is explicitly visible");Check(videos.Rows[0].Cells[0].ToolTipText==v,"Full video path available without renaming source");
 Drop(files,a);Check(files.Rows.Count==1&&videos.Rows.Count==1,"Dropping SRT onto left grid works");Check(((CreatorProject)files.Rows[0].Tag).Video.Length==0,"Separate mismatched-name imports never guessed");C(f,"CreatorPairSelected");Check(((CreatorProject)files.Rows[0].Tag).Video==v,"One click pairs selected differently named SRT and video");Check(info.Text.Contains("Đã ghép"),"Explicit pairing confirms both names");
 C(f,"CreatorImportPaths",(object)new[]{b,v2});Check(((List<CreatorProject>)F(f,"creatorProjects")).Single(p=>p.SourcePath==b).Video==v2,"Exactly one new SRT and video auto-pair despite different names");Check(((CreatorProject)files.CurrentRow.Tag).SourcePath==b,"Newly imported script becomes selection");
 C(f,"CreatorImportPaths",(object)new[]{v2});Check(videos.Rows.Count==2&&info.Text.Contains("đã có"),"Duplicate drop keeps one visible video and explains duplicate");
 string bad=Path.Combine(d,"bad.srt"),unsupported=Path.Combine(d,"x.docx"),missing=Path.Combine(d,"missing.mp4");File.WriteAllText(bad,"this is not SRT");File.WriteAllText(unsupported,"fixture");C(f,"CreatorImportPaths",(object)new[]{missing,unsupported,bad,d});Check(info.Text.Contains("không tìm thấy")&&info.Text.Contains("chưa hỗ trợ")&&info.Text.Contains("bad.srt"),"Missing file, folder, unsupported type and malformed SRT have visible diagnostics");
 using(var dialog=(OpenFileDialog)C(f,"CreatorDialog","Video|*.mp4|Tất cả file|*.*",true,"test")){Check(!dialog.AddExtension&&dialog.DefaultExt==""&&dialog.CheckFileExists&&!dialog.AutoUpgradeEnabled&&dialog.Multiselect,"Compatible file picker never appends MP4, retains existence validation and multiple selection");}
 string orphan=Path.Combine(d,"orphan.webm");File.WriteAllText(orphan,"test");Drop(videos,orphan);Check(videos.Rows.Count==3,"Dropping directly onto video grid works with WEBM");Check(tabs.SelectedTab==(TabPage)F(f,"creatorPage")&&inner.SelectedIndex==0,"Drop stays in import workspace");C(f,"CreatorRemoveVideo");Check(videos.Rows.Count==2&&File.Exists(orphan),"Removing unpaired list item preserves source file");
 File.Delete(v);C(f,"RefreshCreator");Check(videos.Rows.Cast<DataGridViewRow>().Any(row=>(string)row.Tag==v&&row.Cells[1].Value.ToString().Contains("mất")),"Missing old video remains visible for recovery");
 string oldPair=((List<CreatorProject>)F(f,"creatorProjects")).Single(p=>p.SourcePath==a).Video;C(f,"CreatorImportPaths",(object)new[]{a,v2});Check(((List<CreatorProject>)F(f,"creatorProjects")).Single(p=>p.SourcePath==a).Video==oldPair,"Reimport does not silently replace existing pair");
 C(f,"SetBusy",true);Check(!videos.Enabled,"Import and pairing are locked while processing");C(f,"SetBusy",false);Check(videos.Enabled,"Import controls unlock after processing");
 f.Size=new Size(1100,740);Application.DoEvents();using(var bitmap=new Bitmap(f.Width,f.Height)){using(var g=Graphics.FromImage(bitmap))g.CopyFromScreen(f.Location,Point.Empty,f.Size);bitmap.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"validation","creator-import-207.png"));}
 Console.WriteLine("LIST SIZE "+files.Size+" / "+videos.Size+" INFO "+info.Height);Check(files.Width>500&&videos.Width>280&&files.Height>=140&&videos.Visible,"Both lists usable at minimum window");Check(info.Height>=40,"Import messages retain two visible lines at minimum window");Check(File.ReadAllText(a)==srt&&File.ReadAllText(b)==srt,"Import and pairing never rewrite source SRT");
 Console.WriteLine("TOTAL CREATOR IMPORT UI "+count+" passed.");
 }catch(Exception ex){Console.WriteLine(ex);code=1;}finally{f.Close();}};Application.Run(f);Environment.Exit(code);}
}
